B: Time Limit Exceeded
ti ≤T を満たすi のうちci の最小値を求めつつ、そのようなi が存在するか調べていきます。これを実現
するアルゴリズムとして、例えば次のようなアルゴリズムが考えられます。
アルゴリズム1
1.
ans := ∞とする
2.
i = 1, 2, ..., N と順に、ti ≤T かつci < ans ならans := ci とする
3.
ans = ∞なら条件を満たすi は存在しないのでTLE と出力し、そうでなければans を出力する
アルゴリズム2
1.
ti ≤T であるようなi についてci を集めた配列をc′ とする
2.
c′ が空ならTLE と出力し、そうでなければc′ の最小値を求めて出力する
以下は、これらのアルゴリズムをそれぞれC++ で実装した例です。
アルゴリズム1
#include <iostream>
using namespace std ;
const int
i n f {int (1 e9 ) } ;
int main () {
int N, T;
cin >> N >> T;
int ans{ i n f };
for
( int
i = 0;
i < N; ++i ) {
int c ,
t ;
cin >> c >> t ;
i f
( t < T && c < ans ) {
ans = c ;
}
}
i f
( ans == i n f ) {
cout << ”TLE” << endl ;
}
else {
cout << ans << endl ;
}
}

アルゴリズム2
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std ;
int main () {
int N, T;
cin >> N >> T;
vector<int> c (N) ,
t (N) ;
for
( int
i = 0;
i < N; ++i ) {
cin >> c [ i ] >> t [ i ] ;
}
vector<int> f i l t e r e d c ;
for
( int
i = 0;
i < N; ++i ) {
i f
( t [ i ] <= T) {
f i l t e r e d c . push back ( c [ i ] ) ;
}
}
i f
( f i l t e r e d c . s i z e () == 0) {
cout << ”TLE” << endl ;
}
else {
cout << ∗min element ( f i l t e r e d c . begin () ,
f i l t e r e d c . end ( ) ) << endl ;
}
}
